async function importSavedBuilds(file){
 try{
  const data=JSON.parse(await file.text()),raw=Array.isArray(data)?data:data?.builds;if(!Array.isArray(raw))throw Error("shape");
  const allowed=Object.keys(BUILD_TEMPLATES),clean=raw.slice(0,50).map(b=>({id:String(b?.id||Date.now().toString(36)+Math.random().toString(36).slice(2,7)).slice(0,80),name:String(b?.name||"").trim().slice(0,60),type:allowed.includes(b?.type)?b.type:"paladin",level:Math.max(1,Math.min(713,Number(b?.level)||150)),stats:String(b?.stats||"").slice(0,180),notes:String(b?.notes||"").slice(0,1200),createdAt:Number(b?.createdAt)||Date.now(),updatedAt:Number(b?.updatedAt)||Date.now()})).filter(b=>b.name);
  const merged=new Map(state.savedBuilds.map(b=>[b.id,b]));for(const b of clean)merged.set(b.id,b);state.savedBuilds=[...merged.values()].slice(0,50);
  store.set("gb_saved_builds",JSON.stringify(state.savedBuilds));renderSavedBuilds();$("#savedBuildStatus").textContent=t("importDone");
 }catch(e){$("#savedBuildStatus").textContent=t("importInvalid")}
}
